use super::*;
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::*};
#[test]
fn sqlite_snapshot_tiff_erased_text_binary_and_native_preallocation_limits(){
    let source=crate::engine::decode_tiff(&crate::engine::encode_tiff(&raster()).unwrap()).unwrap();let codec=store::ArtifactCodec::bare::<TiffSnapshot,crate::TiffMutation>(crate::STDIO_TIFF_DOCUMENT_SCHEMA);let provider=codec.snapshot_sqlite.unwrap();let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.stdio.tiff".into(),standard:"6.0".into(),subset:"*".into()};for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(<TiffSnapshot as store::ArtifactPack>::encode_pack(&source)),SnapshotEncoding::Text=>store::os_io::IoPayload::Text(<TiffSnapshot as store::ArtifactDsl>::print_dsl(&source))};let database=(provider.export)(crate::STDIO_TIFF_DOCUMENT_SCHEMA,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!((provider.import)(crate::STDIO_TIFF_DOCUMENT_SCHEMA,&dialect,database,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value,payload);}
    let mut huge=raster();huge.ifds[0].entries[0]=long(TAG_IMAGE_WIDTH,u32::MAX);huge.ifds[0].entries[1]=long(TAG_IMAGE_LENGTH,u32::MAX);assert!(huge.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Binary,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err());let mut large=raster();large.ifds[0].entries.push(TiffTag{tag:65535,kind:TiffFieldType::Ascii,values:TiffValues::Ascii("文".repeat(40000))});let mut large_checkpoint=false;let mut callback=|p:SqliteSnapshotProgress|{if p.phase==SqliteSnapshotPhase::EncodeNative&&p.completed>0{large_checkpoint=true;false}else{true}};assert!(large.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Text,&mut SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default())).is_err());assert!(large_checkpoint);assert!(large.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Binary,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:4096,..SqliteDatabaseLimits::default()})).is_err());
}
fn corpus()->serde_json::Value{serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap()}
fn fixture()->TiffSnapshot{let f=corpus();let values=[TiffValues::Byte(vec![0,255]),TiffValues::Ascii(f["ascii"].as_str().unwrap().into()),TiffValues::Short(vec![0,65535]),TiffValues::Long(vec![0,u32::MAX]),TiffValues::Rational(vec![(u32::MAX,0),(1,u32::MAX)]),TiffValues::SByte(vec![i8::MIN,i8::MAX]),TiffValues::Undefined(vec![0,255]),TiffValues::SShort(vec![i16::MIN,i16::MAX]),TiffValues::SLong(vec![i32::MIN,i32::MAX]),TiffValues::SRational(vec![(i32::MIN,0),(i32::MAX,-1)]),TiffValues::Float(f["float32Bits"].as_array().unwrap().iter().map(|v|f32::from_bits(u32::from_str_radix(v.as_str().unwrap(),16).unwrap())).collect()),TiffValues::Double(f["float64Bits"].as_array().unwrap().iter().map(|v|f64::from_bits(u64::from_str_radix(v.as_str().unwrap(),16).unwrap())).collect())];TiffSnapshot{schema:f["schema"].as_str().unwrap().into(),byte_order:TiffByteOrder::BigEndian,ifds:vec![TiffIfd{entries:values.into_iter().map(|values|TiffTag{tag:65535,kind:values.kind(),values}).collect(),pixels:vec![1,2]},TiffIfd{entries:vec![TiffTag{tag:0,kind:TiffFieldType::Double,values:TiffValues::Byte(vec![])}],pixels:f["directoryPixels"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as u8).collect()}],pixels:f["documentPixels"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as u8).collect()}}
fn project(s:&TiffSnapshot)->SqliteDatabase{s.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn restore(d:&SqliteDatabase)->Result<TiffSnapshot,String>{TiffSnapshot::from_sqlite_database(d,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()))}
fn equal(a:&TiffSnapshot,b:&TiffSnapshot){assert_eq!((&a.schema,a.byte_order,&a.pixels),(&b.schema,b.byte_order,&b.pixels));assert_eq!(a.ifds.len(),b.ifds.len());for(a,b)in a.ifds.iter().zip(&b.ifds){assert_eq!(a.pixels,b.pixels);assert_eq!(a.entries.len(),b.entries.len());for(a,b)in a.entries.iter().zip(&b.entries){assert_eq!((a.tag,a.kind),(b.tag,b.kind));match(&a.values,&b.values){(TiffValues::Float(a),TiffValues::Float(b))=>assert_eq!(a.iter().map(|v|v.to_bits()).collect::<Vec<_>>(),b.iter().map(|v|v.to_bits()).collect::<Vec<_>>()),(TiffValues::Double(a),TiffValues::Double(b))=>assert_eq!(a.iter().map(|v|v.to_bits()).collect::<Vec<_>>(),b.iter().map(|v|v.to_bits()).collect::<Vec<_>>()),_=>assert_eq!(a.values,b.values)}}}}
fn oracle(bytes:&[u8],script:&str)->Vec<u8>{use std::{io::Write,process::{Command,Stdio}};let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));output.stdout}

#[test]
fn sqlite_snapshot_tiff_all_owned_values_and_ieee_states_are_lossless(){let s=fixture();let d=project(&s);assert_eq!(d.tables.len(),17);let bytes=export_sqlite_database(&d,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let bytes=oracle(&bytes,"import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');if(d.query('SELECT COUNT(*) AS n FROM tiff_tag WHERE tag_number=65535').get().n!==12)throw Error('duplicate tags');if(d.query('SELECT value_bits,value FROM tiff_float_value WHERE ordinal=6').get().value_bits!==2139095047||d.query('SELECT value FROM tiff_double_value WHERE ordinal=6').get().value!==null)throw Error('NaN exact state');await Bun.write(Bun.stdout,d.serialize());d.close();");equal(&restore(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap(),&s);equal(&restore(&project(&TiffSnapshot::default())).unwrap(),&TiffSnapshot::default());}

#[test]
fn sqlite_snapshot_tiff_independent_named_values_edits_reconstruct(){let mut s=fixture();let bytes=export_sqlite_database(&project(&s),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let bytes=oracle(&bytes,"import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(d.query('SELECT field_type,value_type FROM tiff_tag WHERE id=13').get().field_type!==12||d.query('SELECT value_type FROM tiff_tag WHERE id=13').get().value_type!==1)throw Error('independent owned field types');d.query('UPDATE tiff_ascii_value SET value=?').run('SQLite TIFF 🌠');d.query('UPDATE tiff_rational_value SET denominator=7 WHERE ordinal=0').run();d.query('UPDATE tiff_ifd_pixels SET strip_pixels=? WHERE ifd_id=2').run(new Uint8Array([3,2,1]));await Bun.write(Bun.stdout,d.serialize());d.close();");s.ifds[0].entries[1].values=TiffValues::Ascii(corpus()["editedAscii"].as_str().unwrap().into());if let TiffValues::Rational(v)=&mut s.ifds[0].entries[4].values{v[0].1=7;}s.ifds[1].pixels=vec![3,2,1];equal(&restore(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap(),&s);}

#[test]
fn sqlite_snapshot_tiff_rejects_relational_shapes_ranges_and_limits(){let original=project(&fixture());for alteration in 0..9{let mut d=original.clone();match alteration{0=>d.table_mut("tiff_tag").unwrap().rows[0].values[1]=SqliteValue::Integer(999),1=>d.table_mut("tiff_tag").unwrap().rows[1].values[2]=SqliteValue::Integer(0),2=>d.table_mut("tiff_short_value").unwrap().rows[0].values[3]=SqliteValue::Integer(65536),3=>d.table_mut("tiff_rational_value").unwrap().rows[0].values[4]=SqliteValue::Integer(-1),4=>d.table_mut("tiff_ascii_value").unwrap().rows.clear(),5=>d.table_mut("tiff_byte_value").unwrap().rows[0].values[1]=SqliteValue::Integer(2),6=>d.table_mut("tiff_ifd_pixels").unwrap().rows.pop().map(|_|()).unwrap(),7=>d.table_mut("tiff_float_value").unwrap().rows[0].values[5]=SqliteValue::Text("nan".into()),_=>d.table_mut("tiff_document").unwrap().rows[0].values[2]=SqliteValue::Text("unknown".into())}assert!(restore(&d).is_err(),"alteration {alteration}");}for limits in [SqliteDatabaseLimits{max_rows:2,..SqliteDatabaseLimits::default()},SqliteDatabaseLimits{max_value_bytes:1,..SqliteDatabaseLimits::default()}]{assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(TiffSnapshot::from_sqlite_database(&original,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());}let mut s=fixture();s.ifds[0].entries[1].values=TiffValues::Ascii("x".repeat(100000));let mut count=0;let mut callback=|_|{count+=1;count<2};assert!(s.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default())).is_err());}

#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_tiff_actual_declaration_owned_io_avoids_native_wire_lowering(){use semio_framework_os_kernel::io::{ArtifactDialect,io_mechanism::{io_export_sqlite_snapshot,io_import_sqlite_snapshot}};semio_framework_plugin::Plugin::<semio_framework_plugin::app::NoPluginApp>::builder("stdio").label("TIFF SQLite declaration").version("0.0.1").package_id("semio:stdio").artifact(crate::declaration(crate::definition().unwrap()).unwrap()).try_build().unwrap();let dialect=ArtifactDialect{artifact_kind:"s.stdio.tiff".into(),standard:"6.0".into(),subset:"*".into()};let snapshot=fixture();let mut phases=Vec::new();let bytes=io_export_sqlite_snapshot(&dialect,&snapshot,SnapshotEncoding::Binary,SqliteDatabaseLimits::default(),&mut |p|{phases.push(p.phase);true}).await.unwrap().value;equal(&io_import_sqlite_snapshot::<TiffSnapshot>(&dialect,&bytes,SqliteDatabaseLimits::default(),&mut |_|true).await.unwrap().value,&snapshot);assert!(!phases.iter().any(|p|matches!(p,SqliteSnapshotPhase::DecodeNative|SqliteSnapshotPhase::EncodeNative)));}

#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_tiff_exact_baseline_declaration_owned_io_retains_warnings(){use semio_framework_os_kernel::io::{ArtifactDialect,io_mechanism::{io_export_sqlite_snapshot,io_import_sqlite_snapshot}};semio_framework_plugin::Plugin::<semio_framework_plugin::app::NoPluginApp>::builder("stdio").label("TIFF baseline SQLite declaration").version("0.0.1").package_id("semio:stdio").artifact(crate::declaration(crate::definition().unwrap()).unwrap()).try_build().unwrap();let dialect=ArtifactDialect{artifact_kind:"s.stdio.tiff".into(),standard:"6.0".into(),subset:"baseline".into()};let snapshot=fixture();let expected=crate::standards::v6_0::subsets::baseline::schema::check_tiff_baseline_conformance(&snapshot);let mut phases=Vec::new();let exported=io_export_sqlite_snapshot(&dialect,&snapshot,SnapshotEncoding::Text,SqliteDatabaseLimits::default(),&mut |p|{phases.push(p.phase);true}).await.unwrap();assert_eq!(format!("{:?}",exported.diagnostics),format!("{:?}",expected));let restored=io_import_sqlite_snapshot::<TiffSnapshot>(&dialect,&exported.value,SqliteDatabaseLimits::default(),&mut |_|true).await.unwrap();equal(&restored.value,&snapshot);assert_eq!(format!("{:?}",restored.diagnostics),format!("{:?}",expected));assert!(!phases.iter().any(|p|matches!(p,SqliteSnapshotPhase::DecodeNative|SqliteSnapshotPhase::EncodeNative)));}

fn short(tag:u16,values:Vec<u16>)->TiffTag{TiffTag{tag,kind:TiffFieldType::Short,values:TiffValues::Short(values)}}
fn long(tag:u16,value:u32)->TiffTag{TiffTag{tag,kind:TiffFieldType::Long,values:TiffValues::Long(vec![value])}}
fn raster()->TiffSnapshot{TiffSnapshot{ifds:vec![TiffIfd{entries:vec![long(TAG_IMAGE_WIDTH,1),long(TAG_IMAGE_LENGTH,1),short(TAG_BITS_PER_SAMPLE,vec![8,8,8,8]),short(TAG_COMPRESSION,vec![1]),short(TAG_PHOTOMETRIC,vec![2]),short(TAG_SAMPLES_PER_PIXEL,vec![4])],pixels:vec![]}],pixels:vec![1,2,3,255],..TiffSnapshot::default()}}

#[test]
fn sqlite_snapshot_tiff_native_pack_dsl_states_and_bare_capability_are_preserved(){for byte_order in [TiffByteOrder::LittleEndian,TiffByteOrder::BigEndian]{let mut s=raster();s.byte_order=byte_order;let source=crate::engine::decode_tiff(&crate::engine::encode_tiff(&s).unwrap()).unwrap();let restored=restore(&project(&source)).unwrap();equal(&restored,&source);assert_eq!(<TiffSnapshot as store::ArtifactPack>::encode_pack(&restored),<TiffSnapshot as store::ArtifactPack>::encode_pack(&source));assert_eq!(<TiffSnapshot as store::ArtifactDsl>::print_dsl(&restored),<TiffSnapshot as store::ArtifactDsl>::print_dsl(&source));equal(&<TiffSnapshot as store::ArtifactDsl>::parse_dsl(&<TiffSnapshot as store::ArtifactDsl>::print_dsl(&restored)).unwrap(),&source);let codec=store::ArtifactCodec::bare::<TiffSnapshot,crate::TiffMutation>(crate::STDIO_TIFF_DOCUMENT_SCHEMA);let provider=codec.snapshot_sqlite.unwrap();assert_eq!(provider.snapshot_type,Some(std::any::TypeId::of::<TiffSnapshot>()));let dialect=semio_framework_os_kernel::io_schema::ArtifactDialect{artifact_kind:"s.stdio.tiff".into(),standard:"6.0".into(),subset:"*".into()};let payload=store::os_io::IoPayload::Binary(<TiffSnapshot as store::ArtifactPack>::encode_pack(&source));let database=(provider.export)(crate::STDIO_TIFF_DOCUMENT_SCHEMA,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!((provider.import)(crate::STDIO_TIFF_DOCUMENT_SCHEMA,&dialect,database,SnapshotEncoding::Binary,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value,payload);}}

#[test]
fn sqlite_snapshot_tiff_baseline_guard_matches_native_diagnostics_and_cancels(){let f=corpus();let dialect=|value:&serde_json::Value|semio_framework_os_kernel::io_schema::ArtifactDialect{artifact_kind:value["artifactKind"].as_str().unwrap().into(),standard:value["standard"].as_str().unwrap().into(),subset:value["subset"].as_str().unwrap().into()};for case in f["baselineCases"].as_array().unwrap(){let mut s=raster();s.ifds[0].entries=vec![long(TAG_IMAGE_WIDTH,case["width"].as_u64().unwrap()as u32),long(TAG_IMAGE_LENGTH,case["height"].as_u64().unwrap()as u32),short(TAG_COMPRESSION,vec![case["compression"].as_u64().unwrap()as u16]),short(TAG_PHOTOMETRIC,vec![case["photometric"].as_u64().unwrap()as u16]),short(TAG_BITS_PER_SAMPLE,case["bits"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as u16).collect())];if case["strip"].as_bool().unwrap(){s.ifds[0].entries.push(long(TAG_STRIP_OFFSETS,1));}if case["tile"].as_bool().unwrap(){s.ifds[0].entries.push(long(TAG_TILE_WIDTH,1));}let d=project(&s);let actual=s.validate_sqlite_snapshot_subset(&dialect(&f["sqliteDialect"]),&d,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();let expected=crate::standards::v6_0::subsets::baseline::schema::check_tiff_baseline_conformance(&s);assert_eq!(format!("{:?}",actual.diagnostics),format!("{:?}",expected));for invalid in f["invalidSqliteDialects"].as_array().unwrap(){assert!(s.validate_sqlite_snapshot_subset(&dialect(invalid),&d,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err());}}let mut large=raster();large.ifds[0].entries[2].values=TiffValues::Short(vec![8;10000]);let mut count=0;let mut callback=|_|{count+=1;count<3};assert!(crate::standards::v6_0::subsets::baseline::schema::check_tiff_baseline_conformance_controlled(&large,&mut SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default())).is_err());let mut huge=raster();huge.ifds[0].entries[0]=long(TAG_IMAGE_WIDTH,u32::MAX);huge.ifds[0].entries[1]=long(TAG_IMAGE_LENGTH,u32::MAX);assert!(!crate::standards::v6_0::subsets::baseline::schema::check_tiff_baseline_conformance_controlled(&huge,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().is_empty());}
